create function pg_temp.publish_sync(p_item uuid,p_asset uuid,p_hash text,p_order int,p_duration int default 9,p_forged jsonb default '{"rendererVersion":"untrusted"}',p_trim_start numeric default 0,p_trim_end numeric default null) returns void language sql as $$
 insert into public.playlist_release_items(id,tenant_id,playlist_id,release_id,media_asset_id,media_variant_id,sort_order,duration_seconds,fit_mode,muted,asset_kind,asset_title,storage_path,mime_type,file_size_bytes,checksum_sha256,sync_studio_presentation_json,sync_studio_duration_ms,trim_start_seconds,trim_end_seconds)
 select p_item,'10000000-0000-4000-8000-000000226071','70000000-0000-4000-8000-000000226071','80000000-0000-4000-8000-000000226071',asset.id,variant.id,p_order,p_duration,'contain',true,asset.kind,asset.title,variant.storage_path,variant.mime_type,variant.file_size_bytes,p_hash,p_forged,1,p_trim_start,p_trim_end
 from public.media_assets asset join public.media_variants variant on variant.tenant_id=asset.tenant_id and variant.asset_id=asset.id
 where asset.id=p_asset and asset.tenant_id='10000000-0000-4000-8000-000000226071' limit 1;
$$;
select ok(not has_function_privilege('authenticated','private.freeze_sync_studio_release_item_v1()','EXECUTE'),'the Source freeze helper is not a public writer');
select lives_ok($$select pg_temp.publish_sync('90000000-0000-4000-8000-000000226073','20000000-0000-4000-8000-000000226071',repeat('a',64),0)$$,'the verified complete export publishes with its original Source presentation');
select is((select sync_studio_presentation_json from public.playlist_release_items where id='90000000-0000-4000-8000-000000226073'),(select value->'syncPresentation' from source_document),'caller JSON is ignored in favour of the tenant-scoped immutable export');
select is((select sync_studio_duration_ms from public.playlist_release_items where id='90000000-0000-4000-8000-000000226073'),9000,'the original three-page timing is frozen instead of the supplied value one');
select is((select jsonb_array_length(sync_studio_presentation_json->'rows') from public.playlist_release_items where id='90000000-0000-4000-8000-000000226073'),9,'all nine records and all three pages remain in the release');
select ok((select sites_studio_presentation_json is null from public.playlist_release_items where id='90000000-0000-4000-8000-000000226073'),'Source identity is never stored in the historical Sites column');
update public.studio_project_drafts set document_json=jsonb_set(document_json,'{syncPresentation,title}','"Later concept"') where project_id='30000000-0000-4000-8000-000000226071';
select is((select sync_studio_presentation_json->>'title' from public.playlist_release_items where id='90000000-0000-4000-8000-000000226073'),'Bevestigde Source-versie','a later draft does not alter the published presentation');
select throws_ok($$select pg_temp.publish_sync('90000000-0000-4000-8000-000000226074','20000000-0000-4000-8000-000000226071',repeat('f',64),1)$$,'23514','Studio export checksum does not match the release','a changed export checksum cannot publish');
select throws_ok($$select pg_temp.publish_sync('90000000-0000-4000-8000-000000226075','20000000-0000-4000-8000-000000226071',repeat('a',64),1,6)$$,'23514','Sync release duration does not cover every saved page','a placement cannot truncate the saved three-page sequence');
select throws_ok($$select pg_temp.publish_sync('90000000-0000-4000-8000-000000226080','20000000-0000-4000-8000-000000226071',repeat('a',64),2,9,null,1,null)$$,'23514','Sync release trim does not cover every saved page','trimming the first page cannot publish an incomplete Source loop');
select throws_ok($$select pg_temp.publish_sync('90000000-0000-4000-8000-000000226081','20000000-0000-4000-8000-000000226071',repeat('a',64),2,9,null,0,6)$$,'23514','Sync release trim does not cover every saved page','trimming the last page cannot publish an incomplete Source loop');
select lives_ok($$select pg_temp.publish_sync('90000000-0000-4000-8000-000000226078','20000000-0000-4000-8000-000000226072',repeat('b',64),1)$$,'ordinary historical media remains publishable');
select ok((select sync_studio_presentation_json is null and sync_studio_duration_ms is null from public.playlist_release_items where id='90000000-0000-4000-8000-000000226078'),'caller-supplied Source data cannot be attached to an ordinary photo');
select throws_ok($$update public.playlist_release_items set sync_studio_presentation_json=null,sync_studio_duration_ms=null where id='90000000-0000-4000-8000-000000226073'$$,'23514','playlist releases are immutable','new Source fields retain the complete immutable release guard');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000226071',true);
select is((select count(*) from public.playlist_release_items where tenant_id='10000000-0000-4000-8000-000000226072'),0::bigint,'the Source protocol does not widen cross-tenant reads');
select throws_ok($$select pg_temp.publish_sync('90000000-0000-4000-8000-000000226079','20000000-0000-4000-8000-000000226071',repeat('a',64),2)$$,'42501',null,'direct browser writes cannot bypass the existing publication writer');
select * from finish();
rollback;
